  assert.match(content, /riskData\.ai_provider\s*===\s*['"]ollama['"]/, 'Must check riskData.ai_provider === "ollama"');
  assert.match(content, /remediationData\.ai_provider\s*===\s*['"]ollama['"]/, 'Must check remediationData.ai_provider === "ollama"');
