test('10. Global Provenance Contract: Scenarios A-H evaluation logic', () => {
  // Pure evaluator implementing Step 71 CORE RULE:
  // if ANY visible content block in a card is Ollama-generated -> card provider is 'ollama' (BLUE DOT)
  // otherwise -> 'fallback' (NO DOT)
  function resolveCardProvider(blocks) {
    const hasOllama = blocks.some(b => b.provider === 'ollama');
    return hasOllama ? 'ollama' : 'fallback';
  }

  // A. Entire card generated by Ollama -> blue dot
  const scenarioA = [{ type: 'ai_explanation', provider: 'ollama' }];
  assert.equal(resolveCardProvider(scenarioA), 'ollama');

  // B. One sentence generated by Ollama -> blue dot
  const scenarioB = [
    { type: 'static_header', provider: undefined },
    { type: 'ai_sentence', provider: 'ollama' }
  ];
  assert.equal(resolveCardProvider(scenarioB), 'ollama');

  // C. Mixed deterministic + Ollama content -> blue dot
  const scenarioC = [
    { type: 'deterministic_score', provider: 'fallback' },
    { type: 'ollama_hypothesis', provider: 'ollama' },
    { type: 'database_evidence', provider: undefined }
  ];
  assert.equal(resolveCardProvider(scenarioC), 'ollama');

  // D. Entire card generated by fallback -> no dot
  const scenarioD = [{ type: 'fallback_summary', provider: 'fallback' }];
  assert.equal(resolveCardProvider(scenarioD), 'fallback');

  // E. Ollama online but content not generated by Ollama -> no dot
  // (e.g. system status online, but finding analysis came from rule engine)
  const isOllamaOnline = true;
  const contentProvider = 'fallback'; // content was NOT generated by Ollama
  // Provenance must NEVER be inferred from online status
  assert.notEqual(contentProvider, isOllamaOnline ? 'ollama' : 'fallback');
  assert.equal(contentProvider, 'fallback');

  // F. Ollama unavailable -> fallback/no dot
  const scenarioF = [{ type: 'rule_fallback', provider: 'fallback' }];
  assert.equal(resolveCardProvider(scenarioF), 'fallback');

  // G & H. Multiple cards on same page:
  // Card A contains Ollama content -> dot
  // Card B contains only deterministic content -> no dot
  const pageCardA = [{ type: 'ollama_thesis', provider: 'ollama' }];
  const pageCardB = [{ type: 'raw_evidence_hash', provider: undefined }, { type: 'cwe_title', provider: undefined }];

  assert.equal(resolveCardProvider(pageCardA), 'ollama', 'Card A must receive blue dot');
  assert.equal(resolveCardProvider(pageCardB), 'fallback', 'Card B must NOT receive blue dot');
});

test('11. Deterministic and raw evidence cards intentionally DO NOT display AiProvenanceDot', () => {
  const riskPath = path.join(srcDir, 'pages/RiskPrioritizationPage.tsx');
  const remPath = path.join(srcDir, 'pages/RemediationCenterPage.tsx');

  const riskContent = fs.readFileSync(riskPath, 'utf-8');
  const remContent = fs.readFileSync(remPath, 'utf-8');

  // RiskPrioritizationPage is 100% deterministic formula - must NOT import or render AiProvenanceDot
  assert.ok(!riskContent.includes('AiProvenanceDot'), 'RiskPrioritizationPage must not show AiProvenanceDot');

  // RemediationCenterPage uses rule template logic - must NOT show AiProvenanceDot
  assert.ok(!remContent.includes('AiProvenanceDot'), 'RemediationCenterPage must not show AiProvenanceDot');
});
